function safeStorage(kind){const memory=new Map();let native;try{native=window[kind]}catch{}return{getItem(key){try{return native?native.getItem(key):memory.get(key)??null}catch{native=null;return memory.get(key)??null}},setItem(key,value){if(native){try{return native.setItem(key,value)}catch(error){if(error.name==='QuotaExceededError')throw error;native=null}}memory.set(key,String(value))},removeItem(key){if(native){try{return native.removeItem(key)}catch{native=null}}memory.delete(key)}}}
