function searchModal(){modal('Buscar na loja',`<form onsubmit="event.preventDefault();productQuery=this.q.value;orderQuery=this.q.value;closeModal();go(allowed('products')?'/app/products':'/app/orders')"><div class="field"><label for="globalq">Produto, cliente ou número do pedido</label><input id="globalq" name="q" autofocus placeholder="O que você procura?"></div><div class="form-actions"><button class="btn primary">Buscar</button></div></form>`)}
function periodModal(){modal('Sobre os indicadores',`<p>Os valores são calculados a partir dos pedidos deste ambiente de demonstração. O histórico inicial vai de 17 de setembro a 2 de outubro de 2026.</p><p>Somente pedidos pagos que já saíram para entrega ou foram retirados compõem as vendas e o lucro bruto. Novos testes atualizam os indicadores automaticamente.</p>${button('Entendi','onclick="closeModal()"','primary')}`)}
function render(){if(storefront.init(db))save();const path=routePath();if(path==='/')return go('/loja');if(path.startsWith('/loja')&&typeof renderStore==='function'){renderStore();normalizeLinks();return}if(path.startsWith('/imprimir/')&&typeof renderReceipt==='function'){renderReceipt(Number(path.split('/')[2]));normalizeLinks();return}let page=path.split('/')[2]||'dashboard';if(!allowed(page)){page='dashboard';location.protocol==='file:'?location.hash='/app':history.replaceState({},'',basePath+'#/app')}let content=page==='dashboard'?dashboard():typeof adminPage==='function'?adminPage(page):heading(navigation.find(x=>x[0]===page)?.[1]||'Gestão','Preparando sua loja…');$('#app').innerHTML=shell(page,content);normalizeLinks();document.title=(navigation.find(x=>x[0]===page)?.[1]||'Gestão')+' · Forte Outlet'}
function adminPage(page){const id=Number(routePath().split('/')[3]);switch(page){case'orders':return id?orderDetail(id):ordersPage();case'products':return productsPage();case'inventory':return inventoryPage();case'collections':return collectionsPage();case'customers':return customersPage();case'reports':return reportsPage();case'team':return teamPage();case'store-editor':return editorPage();case'pages':return pagesPage();case'settings':return settingsPage();default:return dashboard()}}
function ordersPage(){const orders=visibleOrders().filter(o=>(orderFilter==='all'||o.status===orderFilter)&&(`${o.id} ${o.customer} ${o.seller}`.toLowerCase().includes(orderQuery.toLowerCase())));return heading('Pedidos','Do primeiro atendimento à casa do cliente.',button('Exportar','onclick="exportOrders()"','','download')+(canSell()?button('Nova pré-venda','onclick="newOrder()"','primary','plus'):''))+`<section class="card"><div class="tabs">${[['all','Todos'],['pending','Pagamento pendente'],['ready','A preparar'],['transit','Em entrega'],['delivered','Concluídos'],['cancelled','Cancelados']].map(([id,label])=>`<button class="tab ${orderFilter===id?'active':''}" onclick="orderFilter='${id}';render()">${label}</button>`).join('')}</div><div class="toolbar"><form class="search" onsubmit="event.preventDefault();orderQuery=this.q.value;render()">${icon('search')}<input name="q" placeholder="Buscar pedido ou cliente" value="${esc(orderQuery)}" aria-label="Buscar pedido"><button aria-label="Buscar">${icon('chevron')}</button></form><span class="subtle">${orders.length} pedidos encontrados</span></div>${orderTable(orders)}</section>`}
function orderDetail(id){const o=visibleOrders().find(o=>o.id===id);if(!o)return heading('Pedido não encontrado','Este pedido não está disponível para o seu perfil.');const sale=completed(o);return `<a class="text-link" href="/app/orders">‹ Todos os pedidos</a><div style="height:19px"></div>`+heading(`Pedido #${o.id}`,`${o.channel} · ${new Date(o.date+'T12:00:00').toLocaleDateString('pt-BR')} · ${o.seller}`,(canPay()&&!completed(o)&&o.status!=='cancelled'?button('Editar dados',`onclick="editOrderModal(${o.id})"`,'','edit'):'')+button('Imprimir pedido',`onclick="go('/imprimir/${o.id}')"`,'','print'))+`<div class="two-col"><div class="stack"><section class="card"><div class="card-header"><h2>Itens do pedido</h2>${badge(o)}</div><div class="tablewrap"><table><thead><tr><th>Produto</th><th>Qtd.</th><th>Total</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${i.qty}</td><td>${money(i.price*i.qty)}</td></tr>`).join('')}</tbody></table></div><div class="pad"><div class="total-line"><span>Produtos</span><strong>${money(orderTotal(o)-o.freight)}</strong></div><div class="total-line"><span>Frete</span><span>${o.freightPending?'A combinar':money(o.freight)}</span></div><div class="total-line final"><span>Total do pedido</span><span>${money(orderTotal(o))}</span></div></div></section><section class="card"><div class="card-header"><h2>Pagamento e comprovante</h2><span class="badge ${o.paid?'green':'yellow'}">${o.paid?'Pago':'Pendente'}</span></div><div class="pad" style="padding-top:0"><div class="total-line"><span class="muted">Forma de pagamento</span><strong>${esc(o.payment)}</strong></div>${o.receipt&&o.receipt!=='demo'?`<img class="receipt-preview" src="${o.receipt}" alt="Comprovante anexado"><p class="subtle">Comprovante anexado neste navegador</p>`:o.receipt==='demo'?`<div class="notice">Pagamento de exemplo já confirmado. Este pedido inicial usa um comprovante fictício.</div>`:`<div class="notice">${o.status==='cancelled'?'Pedido cancelado. Não há pagamento a confirmar.':'Anexe a foto do comprovante para confirmar o pagamento. O pedido continua como pré-venda até a saída da mercadoria.'}</div>`}${canPay()&&!o.paid&&o.status!=='cancelled'?button('Anexar e confirmar pagamento',`onclick="paymentModal(${o.id})"`,'primary','wallet'):''}</div></section><section class="card pad"><h2>Observações do pedido</h2><p style="font-size:14px;line-height:1.7;margin-top:15px">${esc(o.notes||'Nenhuma observação adicionada.')}</p><div class="timeline"><p>Pedido criado · ${esc(o.date)} · ${esc(o.seller)}</p>${o.paid?'<p>Pagamento confirmado e comprovante registrado</p>':''}${sale?'<p>Mercadoria liberada · estoque atualizado · venda contabilizada</p>':''}${o.status==='delivered'?'<p>Entrega ou retirada concluída</p>':''}</div></section></div><div class="stack" style="align-content:start"><section class="card pad"><h2>Etapas do pedido</h2>${[['Pré-venda criada',o.status==='cancelled'?'Reserva liberada após cancelamento':'Produtos reservados no estoque',true],['Pagamento confirmado','Comprovante anexado ao pedido',o.paid],['Saída da mercadoria','Converte a pré-venda em venda',sale],['Pedido concluído','Entrega ou retirada confirmada',o.status==='delivered']].map((s,i)=>`<div class="progress-step ${s[2]?'done':''}"><span class="step-number">${s[2]?'✓':i+1}</span><div>${s[0]}<small>${s[1]}</small></div></div>`).join('')}<div style="margin-top:22px">${o.status==='ready'&&role!=='Vendedor'?button(o.delivery==='Retirada'?'Confirmar retirada':'Liberar para entrega',`onclick="dispatchOrder(${o.id})"`,'primary','truck'):o.status==='transit'&&role!=='Vendedor'?button('Confirmar entrega',`onclick="finishOrder(${o.id})"`,'primary','check'):o.status==='pending'?'<span class="subtle">Aguardando confirmação do pagamento.</span>':''}</div></section><section class="card pad"><h2>Cliente</h2><div class="customer" style="margin:20px 0"><span class="avatar">${initials(o.customer)}</span><strong style="font-size:14px">${esc(o.customer)}</strong></div><p style="font-size:13px;line-height:1.9">${esc(o.phone)}<br>${esc(o.email||'E-mail não informado')}<br>CPF: ${esc(o.cpf)}</p><h3 style="margin:22px 0 10px">${o.delivery==='Retirada'?'Retirada na loja':'Endereço de entrega'}</h3><p style="font-size:13px;line-height:1.8">${esc(o.address)}</p></section>${!sale&&o.status!=='cancelled'&&canManage()?`<div>${button('Cancelar pré-venda',`onclick="cancelOrderModal(${o.id})"`,'danger','trash')}</div>`:''}</div></div>`}
function field(label,name,value='',type='text',extra=''){return `<label class="field ${extra.includes('data-full')?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function parseAddress(value){const blank={cep:'',street:'',number:'',neighborhood:'',city:'',state:'',complement:''};if(value&&typeof value==='object')return {...blank,...value};const match=String(value||'').match(/^(.+?),\s*([^·]+)\s*·\s*([^·]+)\s*·\s*(.+?)\s*\/\s*([A-Za-z]{2})(?:\s*·\s*CEP\s*(\S+))?$/);return match?{...blank,street:match[1].trim(),number:match[2].trim(),neighborhood:match[3].trim(),city:match[4].trim(),state:match[5].toUpperCase(),cep:match[6]||''}:{...blank,street:String(value||'')}}
function addressFields(prefix='',values={}){const v=parseAddress(values),n=key=>prefix?prefix+key[0].toUpperCase()+key.slice(1):key;return `<div class="address-fields" id="${prefix||'admin'}-address-fields"><div class="form-grid">${field('CEP',n('cep'),v.cep,'text','required inputmode="numeric" placeholder="00000-000"')}${field('Rua / avenida',n('street'),v.street,'text','required')}${field('Número',n('number'),v.number,'text','required')}${field('Bairro',n('neighborhood'),v.neighborhood,'text','required')}${field('Cidade',n('city'),v.city,'text','required')}${field('Estado (UF)',n('state'),v.state,'text','required maxlength="2" placeholder="RJ"')}${field('Complemento (opcional)',n('complement'),v.complement,'text','data-full')}</div></div>`}
function addressFromForm(data,prefix=''){const n=key=>prefix?prefix+key[0].toUpperCase()+key.slice(1):key;return Object.fromEntries(['cep','street','number','neighborhood','city','state','complement'].map(key=>[key,String(data[n(key)]||'').trim()]))}
function formatAddress(a){return `${a.street}, ${a.number}${a.complement?' · '+a.complement:''} · ${a.neighborhood} · ${a.city} / ${a.state.toUpperCase()}${a.cep?' · CEP '+a.cep:''}`}
function toggleAdminDelivery(value){const group=$('#admin-address-fields');if(!group)return;const pickup=value==='Retirada';group.classList.toggle('disabled',pickup);group.querySelectorAll('input').forEach(input=>{input.disabled=pickup;input.required=!pickup&&input.name!=='complement'})}
function newOrder(){if(!canSell())return toast('Seu perfil não pode cadastrar pedidos.');modal('Nova pré-venda',`<form id="order-form" onsubmit="event.preventDefault();createAdminOrder(this)"><div class="notice">A mercadoria será reservada. A venda será contabilizada após o pagamento e a saída para entrega.</div><div class="form-grid">${field('Nome do cliente','customer','','text','required')}${field('Telefone / WhatsApp','phone','','tel','required')}${field('CPF','cpf','','text','required')}${field('E-mail (opcional)','email','','email')}<label class="field full">Recebimento<select name="delivery" onchange="toggleAdminDelivery(this.value)"><option>Entrega</option><option>Retirada</option></select></label>${addressFields()}<label class="field full">Produto<select name="product" required oninput="updateOrderEstimate()">${db.products.filter(p=>p.active&&available(p.id)>0).map(p=>`<option value="${p.id}">${esc(p.name)} · ${money(p.price)} · ${available(p.id)} disponíveis</option>`).join('')}</select></label>${field('Quantidade','qty',1,'number','min="1" max="99" required oninput="updateOrderEstimate()"')}<label class="field">Vendedor<select name="seller">${(role==='Vendedor'?[{name:currentSeller}]:db.team.filter(t=>t.active&&['Vendedor','Gerente','Proprietário'].includes(t.role))).map(t=>`<option>${esc(t.name)}</option>`).join('')}</select></label><label class="field">Pagamento<select name="payment"><option>Pix</option><option>Cartão de crédito</option><option>Cartão de débito</option><option>Dinheiro</option></select></label>${field('Frete (R$)','freight',0,'number','min="0" step="0.01" required oninput="updateOrderEstimate()"')}<label class="field full">Observações<textarea name="notes" placeholder="Preferência de entrega, referência do endereço…"></textarea></label></div><div class="total-line final"><span>Total</span><span id="order-estimate">${money(db.products.find(p=>p.active&&available(p.id)>0)?.price)}</span></div><div class="form-actions">${button('Cancelar','type="button" onclick="closeModal()"')}<button class="btn primary">Criar pré-venda</button></div></form>`)}
function updateOrderEstimate(){const f=$('#order-form');const p=db.products.find(p=>p.id===Number(f.product.value));$('#order-estimate').textContent=money((p?.price||0)*Number(f.qty.value)+Number(f.freight.value))}
function createAdminOrder(form){if(!canSell())return;const f=Object.fromEntries(new FormData(form));const p=db.products.find(p=>p.id===Number(f.product));const qty=Number(f.qty);if(!p||!Number.isInteger(qty)||qty<1||qty>available(p.id))return toast('Quantidade indisponível em estoque.');const addressParts=f.delivery==='Retirada'?(db.settings.addressParts||parseAddress(db.settings.address)):addressFromForm(f);const o={...f,addressParts,address:f.delivery==='Retirada'?db.settings.address:formatAddress(addressParts),id:Math.max(1000,...db.orders.map(o=>o.id))+1,date:new Date().toLocaleDateString('en-CA'),freight:Number(f.freight),items:[{id:p.id,name:p.name,price:p.price,cost:p.cost,qty}],status:'pending',paid:false,receipt:null,channel:'Loja física',seller:role==='Vendedor'?currentSeller:f.seller};db.orders.unshift(o);if(save()){closeModal();go('/app/orders/'+o.id);toast('Pré-venda criada. Produtos reservados.')}}
function paymentModal(id){const o=visibleOrders().find(o=>o.id===id);if(!o||!canPay()||o.status!=='pending')return;if(o.freightPending)return toast('Confirme o frete em Editar dados antes de receber o pagamento.');modal('Confirmar pagamento',`<form onsubmit="event.preventDefault();confirmPayment(${id},this)"><p>Pedido <strong>#${id}</strong> · ${esc(o.customer)}<br>Total a confirmar: <strong>${money(orderTotal(o))}</strong></p><label class="field">Foto do comprovante<input type="file" name="receipt" accept="image/png,image/jpeg,image/webp" required></label><p class="subtle" style="margin-top:10px">PNG, JPG ou WebP · até 2 MB. Use um arquivo de teste.</p><label style="display:flex;gap:9px;font-size:13px;line-height:1.6"><input type="checkbox" required>Conferi o valor recebido e o comprovante deste pedido.</label><div class="form-actions">${button('Cancelar','type="button" onclick="closeModal()"')}<button class="btn primary">Confirmar pagamento</button></div></form>`)}
async function imageData(file){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024)throw Error('Selecione uma imagem PNG, JPG ou WebP de até 2 MB.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Não foi possível ler a imagem.'));r.readAsDataURL(file)})}
async function confirmPayment(id,form){const o=visibleOrders().find(o=>o.id===id);if(!o||!canPay()||o.status!=='pending')return;try{const data=await imageData(form.receipt.files[0]);o.receipt=data;o.paid=true;o.status='ready';if(!save()){o.receipt=null;o.paid=false;o.status='pending';return}closeModal();render();toast('Pagamento confirmado. Pedido pronto para preparação.')}catch(e){toast(e.message)}}
function dispatchOrder(id){const o=db.orders.find(o=>o.id===id);if(!o||role==='Vendedor'||!o.paid||!o.receipt||o.status!=='ready')return toast('Confirme o pagamento com comprovante antes da saída.');for(const i of o.items){const p=db.products.find(p=>p.id===i.id);if(!p||p.stock<i.qty)return toast('Estoque insuficiente para liberar o pedido.')}modal(o.delivery==='Retirada'?'Confirmar retirada':'Liberar para entrega',`<p>Confirmar a saída do pedido <strong>#${id}</strong>? Esta ação dará baixa em ${o.items.reduce((n,i)=>n+i.qty,0)} item(ns) e contabilizará ${money(orderTotal(o)-o.freight)} em vendas.</p><div class="form-actions">${button('Voltar','onclick="closeModal()"')}${button('Confirmar saída',`onclick="commitDispatch(${id})"`,'primary')}</div>`)}
function commitDispatch(id){const o=db.orders.find(o=>o.id===id);if(!o||role==='Vendedor'||o.status!=='ready'||!o.paid||!o.receipt)return;for(const i of o.items){const p=db.products.find(p=>p.id===i.id);if(!p||p.stock<i.qty)return toast('O estoque mudou. Confira os itens.')}o.items.forEach(i=>{db.products.find(p=>p.id===i.id).stock-=i.qty;db.movements.unshift({id:Date.now()+i.id,product:i.name,qty:-i.qty,reason:'Saída do pedido #'+id,date:new Date().toLocaleString('pt-BR'),by:role})});o.status=o.delivery==='Retirada'?'delivered':'transit';save();closeModal();render();toast('Saída registrada. Estoque e vendas atualizados.')}
function finishOrder(id){const o=db.orders.find(o=>o.id===id);if(!o||o.status!=='transit'||role==='Vendedor')return;o.status='delivered';save();render();toast('Entrega concluída.')}
function cancelOrderModal(id){if(!canManage())return;modal('Cancelar pré-venda',`<p>O pedido #${id} será cancelado e os produtos reservados voltarão a ficar disponíveis.${db.orders.find(o=>o.id===id)?.paid?' O pagamento já confirmado deve ser estornado separadamente; este protótipo não realiza reembolsos.':''}</p><div class="form-actions">${button('Manter pedido','onclick="closeModal()"')}${button('Cancelar pré-venda',`onclick="cancelOrder(${id})"`,'danger')}</div>`)}
function cancelOrder(id){const o=db.orders.find(o=>o.id===id);if(!canManage()||!o||completed(o))return;o.status='cancelled';save();closeModal();render();toast('Pedido cancelado. Reserva de estoque liberada.')}
function productsPage(){const products=db.products.filter(p=>(p.name+' '+p.sku+' '+p.category).toLowerCase().includes(productQuery.toLowerCase()));return heading('Produtos','Um catálogo único para sua loja física e online.',button('Adicionar produto','onclick="productModal()"','primary','plus'))+`<section class="card"><div class="toolbar"><form class="search" onsubmit="event.preventDefault();productQuery=this.q.value;render()">${icon('search')}<input name="q" value="${esc(productQuery)}" placeholder="Buscar por nome, SKU ou coleção" aria-label="Buscar produtos"><button aria-label="Buscar">${icon('chevron')}</button></form><span class="subtle">${products.length} produtos</span></div><div class="tablewrap"><table><thead><tr><th>Produto</th><th>Status</th><th>Disponível</th><th>Coleção</th><th>Preço</th><th></th></tr></thead><tbody>${products.map(p=>`<tr class="clickable" tabindex="0" onkeydown="if(event.key==='Enter'){this.click()}" onclick="productModal(${p.id})"><td><div class="product-cell"><img src="${esc(p.image)}" alt=""><div>${esc(p.name)}<small>${esc(p.sku)}</small></div></div></td><td><span class="badge ${p.active?'green':'gray'}">${p.active?'Ativo':'Rascunho'}</span></td><td>${available(p.id)} un. ${available(p.id)<=p.min?'<span class="badge yellow">Baixo</span>':''}</td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td>${icon('edit')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhum produto encontrado.</td></tr>'}</tbody></table></div></section>`}
function productModal(id){if(!canManage())return;const p=db.products.find(p=>p.id===id)||{name:'',price:0,cost:0,stock:0,min:3,sku:'',image:'',category:db.collections[0],active:true,description:''};modal(id?'Editar produto':'Novo produto',`<form onsubmit="event.preventDefault();saveProduct(this,${id||0})"><div class="form-grid">${field('Nome do produto','name',p.name,'text','required data-full')}${field('SKU / código','sku',p.sku,'text','required') }<label class="field">Coleção<select name="category">${db.collections.map(c=>`<option ${c===p.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label>${field('Preço de venda (R$)','price',p.price,'number','min="0.01" step="0.01" required')}${field('Custo do produto (R$)','cost',p.cost,'number','min="0" step="0.01" required')}${id?'':field('Estoque inicial','stock',p.stock,'number','min="0" step="1" required')}${field('Alerta de estoque mínimo','min',p.min,'number','min="0" step="1" required')}<label class="field">Visibilidade<select name="active"><option value="true" ${p.active?'selected':''}>Ativo na loja online</option><option value="false" ${!p.active?'selected':''}>Rascunho</option></select></label><label class="field full">Descrição<textarea name="description" required>${esc(p.description)}</textarea></label>${field('URL da foto (https://)','image',p.image?.startsWith('data:')?'':p.image,'url','data-full')}<label class="field full">Ou enviar foto<input name="photo" type="file" accept="image/png,image/jpeg,image/webp"><small>Até 2 MB. A foto atual é preservada se você não enviar outra.</small></label></div><div class="form-actions">${button('Cancelar','type="button" onclick="closeModal()"')}<button class="btn primary">Salvar produto</button></div></form>`)}
async function saveProduct(form,id){if(!canManage())return;const f=Object.fromEntries(new FormData(form));let image=f.image;try{if(form.photo.files[0])image=await imageData(form.photo.files[0]);else if(!image)image=db.products.find(p=>p.id===id)?.image;if(!image)return toast('Adicione uma foto ao produto.');if(!image.startsWith('https://')&&!image.startsWith('data:image/'))return toast('Use uma URL HTTPS para a foto.');if(db.products.some(p=>p.sku===f.sku&&p.id!==id))return toast('Este SKU já está em uso.');const data={name:f.name.trim(),sku:f.sku.trim(),category:f.category,description:f.description,price:Number(f.price),cost:Number(f.cost),min:Number(f.min),active:f.active==='true',image};if(!Number.isInteger(data.min)||(!id&&!Number.isInteger(Number(f.stock))))return toast('Informe quantidades inteiras.');if(id)Object.assign(db.products.find(p=>p.id===id),data);else db.products.push({...data,id:Math.max(0,...db.products.map(p=>p.id))+1,stock:Number(f.stock)});if(save()){closeModal();render();toast('Produto salvo. A vitrine já foi atualizada.')}}catch(e){toast(e.message)}}
function inventoryPage(){return heading('Estoque','Controle o que entrou, o que está reservado e o que pode ser vendido.',button('Movimentar estoque','onclick="stockModal()"','primary','plus'))+metrics([['Estoque físico',db.products.reduce((n,p)=>n+p.stock,0),'Unidades na loja','box'],['Reservado',db.products.reduce((n,p)=>n+reserved(p.id),0),'Pré-vendas em andamento','clock'],['Disponível',db.products.reduce((n,p)=>n+available(p.id),0),'Pronto para novas vendas','store'],['Estoque baixo',db.products.filter(p=>available(p.id)<=p.min).length,'Produtos para repor','layers']])+`<div class="stack"><section class="card"><div class="card-header"><h2>Posição de estoque</h2><span class="subtle">A baixa ocorre na saída da mercadoria</span></div><div class="tablewrap"><table><thead><tr><th>Produto</th><th>Físico</th><th>Reservado</th><th>Disponível</th><th>Situação</th><th></th></tr></thead><tbody>${db.products.map(p=>`<tr><td><div class="product-cell"><img src="${esc(p.image)}" alt=""><div>${esc(p.name)}<small>${esc(p.sku)}</small></div></div></td><td>${p.stock}</td><td>${reserved(p.id)}</td><td><strong>${available(p.id)}</strong></td><td><span class="badge ${available(p.id)<=p.min?'yellow':'green'}">${available(p.id)<=p.min?'Repor estoque':'Regular'}</span></td><td>${button('Movimentar',`onclick="stockModal(${p.id})"`,'small')}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="card-header"><h2>Histórico de movimentações</h2></div>${db.movements.length?`<div class="tablewrap"><table><thead><tr><th>Data</th><th>Produto</th><th>Movimento</th><th>Motivo</th><th>Responsável</th></tr></thead><tbody>${db.movements.map(m=>`<tr><td>${esc(m.date)}</td><td>${esc(m.product)}</td><td><span class="badge ${m.qty>0?'green':'yellow'}">${m.qty>0?'+':''}${m.qty} un.</span></td><td>${esc(m.reason)}</td><td>${esc(m.by)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">As entradas e saídas que você registrar aparecerão aqui.</div>'}</section></div>`}
function stockModal(id){if(!allowed('inventory'))return;modal('Movimentar estoque',`<form onsubmit="event.preventDefault();saveStock(this)"><div class="form-grid">${field('Pesquisar produto','productSearch','','search','data-full oninput="filterStockProducts(this.value)" placeholder="Digite o nome ou código do produto"')}<label class="field full">Produto<select name="product" id="stock-product">${db.products.map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${esc(p.name)} · ${esc(p.sku)}</option>`).join('')}</select></label><label class="field">Tipo de movimentação<select name="type"><option value="in">Entrada</option><option value="out">Saída</option></select></label>${field('Quantidade','qty',1,'number','min="1" step="1" required')}${field('Motivo / referência','reason','','text','required data-full placeholder="Ex.: Recebimento do fornecedor, NF 123"')}</div><div class="notice" style="margin-top:20px">Saídas de vendas devem ser confirmadas no pedido. Ajustes manuais não podem consumir o estoque reservado.</div><div class="form-actions"><button class="btn primary">Registrar movimento</button></div></form>`)}
function filterStockProducts(query){const select=$('#stock-product'),selected=select.value;const matches=db.products.filter(p=>(p.name+' '+p.sku).toLocaleLowerCase('pt-BR').includes(query.trim().toLocaleLowerCase('pt-BR')));select.innerHTML=matches.length?matches.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.sku)}</option>`).join(''):'<option value="" disabled>Nenhum produto encontrado</option>';if(matches.some(p=>String(p.id)===selected))select.value=selected;else if(!matches.length)select.value='';select.disabled=!matches.length}
function saveStock(form){if(!allowed('inventory'))return;const f=Object.fromEntries(new FormData(form));const p=db.products.find(p=>p.id===Number(f.product));let qty=Number(f.qty);if(!p||!Number.isInteger(qty)||qty<1)return toast('Informe uma quantidade válida.');if(f.type==='out'&&qty>available(p.id))return toast('Saída maior que o estoque disponível.');qty*=f.type==='out'?-1:1;p.stock+=qty;db.movements.unshift({id:Date.now(),product:p.name,qty,reason:f.reason,date:new Date().toLocaleString('pt-BR'),by:role});save();closeModal();render();toast('Movimentação registrada.')}
function collectionsPage(){return heading('Coleções','Organize a vitrine por ambientes e tipos de produto.',button('Nova coleção','onclick="collectionModal()"','primary','plus'))+`<div class="collection-grid">${db.collections.map((c,i)=>{const products=db.products.filter(p=>p.category===c);return `<section class="card collection-card">${products[0]?`<img src="${products[0].image}" alt="${esc(c)}">`:'<div class="empty">Nenhum produto nesta coleção</div>'}<div class="pad"><div><h2>${esc(c)}</h2><small>${products.length} produtos</small></div><button aria-label="Editar coleção" onclick="collectionModal(${i})">${icon('edit')}</button></div></section>`}).join('')}</div>`}
function collectionModal(index){if(!canManage())return;modal(index===undefined?'Nova coleção':'Editar coleção',`<form onsubmit="event.preventDefault();saveCollection(this,${index===undefined?-1:index})">${field('Nome da coleção','name',db.collections[index]||'','text','required')}<div class="form-actions"><button class="btn primary">Salvar coleção</button></div></form>`)}
function saveCollection(form,index){const name=form.elements.name.value.trim();if(!canManage()||!name)return;if(db.collections.some((c,i)=>c.toLowerCase()===name.toLowerCase()&&i!==index))return toast('Já existe uma coleção com este nome.');if(index>=0){const previous=db.collections[index];db.collections[index]=name;db.products.forEach(p=>{if(p.category===previous)p.category=name})}else db.collections.push(name);save();closeModal();render();toast('Coleção atualizada na loja.')}
function customersPage(){const customers=[...new Set(visibleOrders().map(o=>o.customer))].map(name=>{const orders=visibleOrders().filter(o=>o.customer===name);return{...orders[0],orders:orders.length,spent:orders.filter(completed).reduce((n,o)=>n+orderTotal(o),0)}});return heading('Clientes','Histórico de relacionamento e compras em um só lugar.')+`<section class="card"><div class="card-header"><h2>${customers.length} clientes</h2><span class="subtle">Cadastrados a partir dos pedidos</span></div><div class="tablewrap"><table><thead><tr><th>Cliente</th><th>Contato</th><th>Pedidos</th><th>Compras realizadas</th><th></th></tr></thead><tbody>${customers.map(c=>`<tr class="clickable" tabindex="0" onkeydown="if(event.key==='Enter'){this.click()}" onclick="customerModal('${encodeURIComponent(c.customer).replace(/'/g,'%27')}')"><td><div class="customer"><span class="avatar">${initials(c.customer)}</span>${esc(c.customer)}</div></td><td>${esc(c.phone)}<small style="display:block">${esc(c.email)}</small></td><td>${c.orders}</td><td>${money(c.spent)}</td><td>${icon('chevron')}</td></tr>`).join('')}</tbody></table></div></section>`}
function customerModal(encoded){const name=decodeURIComponent(encoded),orders=visibleOrders().filter(o=>o.customer===name),c=orders[0];modal(esc(name),`<p>${esc(c.email)}<br>${esc(c.phone)}<br>${esc(c.address)}</p><h3 style="margin-bottom:12px">Histórico de pedidos</h3>${orders.map(o=>`<div class="total-line"><a href="/app/orders/${o.id}" onclick="closeModal()">#${o.id} · ${money(orderTotal(o))}</a>${badge(o)}</div>`).join('')}`)}
function reportsPage(){const orders=db.orders.filter(completed),sales=orders.reduce((n,o)=>n+orderTotal(o)-o.freight,0),cost=orders.reduce((n,o)=>n+o.items.reduce((s,i)=>s+i.cost*i.qty,0),0),profit=sales-cost;return heading('Relatórios','Os números por trás das decisões da sua loja.',button('Exportar relatório','onclick="exportReport()"','','download'))+metrics([['Receita de produtos',money(sales),orders.length+' vendas realizadas','wallet'],['Custo das mercadorias',money(cost),'Custo registrado no momento do pedido','box'],['Lucro bruto',money(profit),'Receita de produtos − custo','chart'],['Margem bruta',(sales?profit/sales*100:0).toFixed(1).replace('.',',')+'%','Sobre a receita de produtos','layers']])+`<div class="notice">Lucro bruto considera apenas vendas com pagamento e saída confirmados. Frete, taxas, impostos e despesas operacionais não entram neste cálculo.</div><div class="two-col"><section class="card"><div class="card-header"><h2>Vendas por vendedor</h2></div><div class="tablewrap"><table><thead><tr><th>Vendedor</th><th>Vendas</th><th>Receita</th><th>Lucro bruto</th></tr></thead><tbody>${[...new Set(orders.map(o=>o.seller))].map(s=>{const os=orders.filter(o=>o.seller===s);return `<tr><td>${esc(s)}</td><td>${os.length}</td><td>${money(os.reduce((n,o)=>n+orderTotal(o)-o.freight,0))}</td><td>${money(os.reduce((n,o)=>n+o.items.reduce((t,i)=>t+(i.price-i.cost)*i.qty,0),0))}</td></tr>`}).join('')}</tbody></table></div></section><section class="card pad"><h2>Participação por canal</h2>${['Loja física','Loja online'].map(c=>{const total=orders.filter(o=>o.channel===c).reduce((n,o)=>n+orderTotal(o)-o.freight,0);return `<div style="margin-top:26px"><div class="total-line"><span>${c}</span><strong>${money(total)}</strong></div><div class="seller-bar"><i style="width:${sales?total/sales*100:0}%"></i></div></div>`}).join('')}</section></div><section class="card" style="margin-top:23px"><div class="card-header"><h2>Vendas que compõem o relatório</h2></div>${orderTable(orders)}</section>`}
function teamPage(){return heading('Equipe e permissões','Cada pessoa com acesso ao que precisa para trabalhar.',button('Adicionar pessoa','onclick="teamModal()"','primary','plus'))+`<div class="notice">Os perfis abaixo simulam as permissões da operação. Nesta fase visual, não há login seguro nem convites por e-mail. Use o avatar no canto superior para testar cada cargo.</div><div class="stack"><section class="card"><div class="tablewrap"><table><thead><tr><th>Pessoa</th><th>E-mail</th><th>Função</th><th>Status</th><th></th></tr></thead><tbody>${db.team.map(t=>`<tr><td><div class="customer"><span class="avatar">${initials(t.name)}</span>${esc(t.name)}</div></td><td>${esc(t.email)}</td><td>${t.role}</td><td><span class="badge ${t.active?'green':'gray'}">${t.active?'Ativo':'Inativo'}</span></td><td>${t.role==='Proprietário'?'':button('Editar',`onclick="teamModal(${t.id})"`,'small')}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="card-header"><h2>O que cada função pode fazer</h2></div><div class="tablewrap"><table class="permission-table"><thead><tr><th>Permissão</th><th>Proprietário</th><th>Gerente</th><th>Vendedor</th><th>Estoque</th></tr></thead><tbody>${[['Ver pedidos','Todos','Todos','Próprios','Todos'],['Criar pré-vendas','✓','✓','✓','—'],['Confirmar pagamento','✓','✓','Próprios','—'],['Liberar entrega / retirada','✓','✓','—','✓'],['Produtos e loja online','✓','✓','—','—'],['Movimentar estoque','✓','✓','—','✓'],['Custos e lucro bruto','✓','✓','—','—'],['Gerenciar equipe','✓','Vendedores / estoque','—','—'],['Configurações da loja','✓','—','—','—']].map(row=>`<tr>${row.map((c,i)=>`<td class="${c==='✓'?'check':c==='—'?'dash':''}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section></div>`}
function teamModal(id){if(!canManage())return;const t=db.team.find(t=>t.id===id)||{name:'',email:'',role:'Vendedor',active:true};if(t.role==='Proprietário'||role==='Gerente'&&t.role==='Gerente')return toast('Este perfil só pode ser alterado pelo proprietário.');modal(id?'Editar pessoa':'Adicionar pessoa',`<form onsubmit="event.preventDefault();saveTeam(this,${id||0})"><div class="form-grid">${field('Nome completo','name',t.name,'text','required')}${field('E-mail','email',t.email,'email','required')}<label class="field">Função<select name="role">${(role==='Proprietário'?['Gerente','Vendedor','Estoque']:['Vendedor','Estoque']).map(r=>`<option ${r===t.role?'selected':''}>${r}</option>`).join('')}</select></label><label class="field">Status<select name="active"><option value="true" ${t.active?'selected':''}>Ativo</option><option value="false" ${!t.active?'selected':''}>Inativo</option></select></label></div><div class="form-actions"><button class="btn primary">Salvar pessoa</button></div></form>`)}
function saveTeam(form,id){if(!canManage())return;const f=Object.fromEntries(new FormData(form));if(db.team.some(t=>t.email.toLowerCase()===f.email.toLowerCase()&&t.id!==id))return toast('Este e-mail já está cadastrado.');const existing=db.team.find(t=>t.id===id);if(existing?.role==='Proprietário'||role==='Gerente'&&(existing?.role==='Gerente'||f.role==='Gerente'))return;const data={name:f.name,email:f.email,role:f.role,active:f.active==='true'};if(id)Object.assign(existing,data);else db.team.push({...data,id:Date.now()});save();closeModal();render();toast('Pessoa salva no ambiente de demonstração.')}
function editorPage(){return storefront.editorPage()}
function pagesPage(){return heading('Páginas','As informações que ajudam seu cliente a comprar com confiança.',button('Nova página','onclick="pageModal()"','primary','plus'))+`<section class="card"><div class="tablewrap"><table><thead><tr><th>Título</th><th>Visibilidade</th><th></th></tr></thead><tbody>${db.pages.map(p=>`<tr class="clickable" tabindex="0" onkeydown="if(event.key==='Enter'){this.click()}" onclick="pageModal(${p.id})"><td>${esc(p.title)}</td><td><span class="badge ${p.active?'green':'gray'}">${p.active?'Visível na loja':'Rascunho'}</span></td><td>${icon('edit')}</td></tr>`).join('')}</tbody></table></div></section>`}
function pageModal(id){if(!canManage())return;const p=db.pages.find(p=>p.id===id)||{title:'',content:'',active:true};modal(id?'Editar página':'Nova página',`<form onsubmit="event.preventDefault();savePage(this,${id||0})"><div class="form-grid">${field('Título','title',p.title,'text','required data-full')}<label class="field full">Conteúdo<textarea style="min-height:190px" name="content" required>${esc(p.content)}</textarea></label><label class="field full">Visibilidade<select name="active"><option value="true" ${p.active?'selected':''}>Visível na loja</option><option value="false" ${!p.active?'selected':''}>Rascunho</option></select></label></div><div class="form-actions"><button class="btn primary">Salvar página</button></div></form>`)}
function savePage(form,id){if(!canManage())return;const f=Object.fromEntries(new FormData(form));const data={title:f.title,content:f.content,active:f.active==='true'};if(id)Object.assign(db.pages.find(p=>p.id===id),data);else db.pages.push({...data,id:Date.now()});save();closeModal();render();toast('Página salva na loja.')}
function settingsPage(){const a=db.settings.addressParts||parseAddress(db.settings.address);return heading('Configurações','As informações que acompanham seus pedidos.')+`<div class="settings-grid"><section class="card pad"><h2 style="margin-bottom:22px">Dados da loja</h2><form onsubmit="event.preventDefault();saveSettings(this)"><div class="form-grid">${field('Nome da loja','name',db.settings.name,'text','required')}${field('WhatsApp da loja (com DDI e DDD)','phone',db.settings.phone,'tel','placeholder="5521999999999" pattern="[0-9]{12,13}"')}${addressFields('store',a)}</div><p class="subtle" style="line-height:1.7;margin-top:18px">Ao configurar o número, o checkout oferece um botão para abrir o WhatsApp com o resumo do pedido. Nenhuma mensagem é enviada automaticamente nesta demonstração.</p><div class="form-actions"><button class="btn primary">Salvar dados</button></div></form></section><section class="card pad"><h2>Sobre esta demonstração</h2><p style="font-size:14px;line-height:1.8;margin:15px 0">O catálogo, os pedidos, os comprovantes e as alterações ficam neste navegador. Os dados iniciais de clientes, custos, estoque e vendas são fictícios. Os produtos e as fotos usam a loja atual como referência.</p><p class="subtle" style="line-height:1.8">Autenticação, permissões no servidor, pagamentos, envio automático de WhatsApp e sincronização entre dispositivos serão conectados na etapa de backend. O documento impresso é um pedido de venda não fiscal.</p><div class="form-actions">${button('Restaurar dados de demonstração','onclick="resetModal()"','danger')}</div></section></div>`}
function saveSettings(form){if(role!=='Proprietário')return;const data=Object.fromEntries(new FormData(form));const addressParts=addressFromForm(data,'store');Object.assign(db.settings,{name:data.name,phone:data.phone,addressParts,address:formatAddress(addressParts)});save();render();toast('Dados da loja salvos.')}
function resetModal(){modal('Restaurar demonstração',`<p>Isso remove os pedidos, comprovantes e alterações que você criou neste navegador e restaura os exemplos iniciais.</p><div class="form-actions">${button('Manter meus dados','onclick="closeModal()"')}${button('Restaurar exemplos','onclick="db=defaults();save();closeModal();render();toast(\'Demonstração restaurada.\')"','danger')}</div>`)}
function downloadCSV(name,rows){const clean=x=>{const s=String(x??'');return '"'+(/^[=+@-]/.test(s)?"'":'')+s.replace(/"/g,'""')+'"'};const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(clean).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Arquivo CSV gerado.')}
function exportOrders(){downloadCSV('pedidos-forte-outlet.csv',[['Pedido','Cliente','Data','Vendedor','Status','Total'],...visibleOrders().map(o=>[o.id,o.customer,o.date,o.seller,statuses[o.status][0],orderTotal(o).toFixed(2)])])}
function exportReport(){if(!canManage())return;downloadCSV('lucro-bruto-forte-outlet.csv',[['Pedido','Data','Vendedor','Receita de produtos','Custo','Lucro bruto'],...db.orders.filter(completed).map(o=>{const sale=orderTotal(o)-o.freight,cost=o.items.reduce((n,i)=>n+i.cost*i.qty,0);return[o.id,o.date,o.seller,sale.toFixed(2),cost.toFixed(2),(sale-cost).toFixed(2)]})])}
function renderReceipt(id){const o=visibleOrders().find(o=>o.id===id);if(!o){$('#app').innerHTML='<div class="empty">Pedido não encontrado.</div>';return}document.title='Pedido '+id+' · Forte Outlet';$('#app').innerHTML=`<div class="print-actions">${button('Voltar ao pedido',`onclick="go('/app/orders/${id}')"`,'','back')}${button('Imprimir / salvar PDF','onclick="window.print()"','primary','print')}</div><article class="receipt"><header><img src="assets/logo.webp" alt="Grupo Outlet"><div><h1>${esc(db.settings.name)}</h1><p style="margin-top:7px;font-size:12px">forteoutlet.com.br<br>${esc(db.settings.address)}</p></div><h2 style="white-space:nowrap">Pedido #${o.id}</h2></header><div class="details"><div><strong>INFORMAÇÕES DO PEDIDO</strong><br>Data: ${new Date(o.date+'T12:00:00').toLocaleDateString('pt-BR')}<br>Status: ${statuses[o.status][0]}<br>Cliente: ${esc(o.customer)}<br>CPF: ${esc(o.cpf)}</div><div><strong>CONTATO & ENTREGA</strong><br>Telefone: ${esc(o.phone)}<br>Tipo: ${esc(o.delivery)}<br>Vendedor(a): ${esc(o.seller)}${o.deliveryDate?'<br>Previsão: '+esc(o.deliveryDate.split('-').reverse().join('/')):''}</div><div><strong>ENDEREÇO DO CLIENTE</strong><br>${esc(o.customer)}<br>${esc(o.address)}</div></div><h2>Produtos</h2><table><thead><tr><th>CÓD.</th><th>DESCRIÇÃO</th><th>QTD.</th><th>PREÇO UN.</th><th>TOTAL</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${esc(db.products.find(p=>p.id===i.id)?.sku||i.id)}</td><td style="white-space:normal">${esc(i.name)}</td><td>${i.qty}</td><td>${money(i.price)}</td><td>${money(i.price*i.qty)}</td></tr>`).join('')}</tbody></table><div style="margin-left:auto;max-width:330px;padding-top:20px"><div class="total-line"><span>Subtotal</span><span>${money(orderTotal(o)-o.freight)}</span></div><div class="total-line"><span>Frete</span><span>${money(o.freight)}</span></div><div class="total-line"><span>Quantidade total</span><span>${o.items.reduce((n,i)=>n+i.qty,0)}</span></div><div class="total-line final"><span>TOTAL</span><span>${money(orderTotal(o))}</span></div></div><h2>Informações de pagamento</h2><div class="total-line"><span>${esc(o.payment)} · ${o.paid?'Pagamento confirmado':'Aguardando pagamento'}</span><strong>${money(o.paid?orderTotal(o):0)}</strong></div><h2>Observações</h2><p style="line-height:1.8;min-height:60px">${esc(o.notes||'Sem observações.')}<br>Vendedor(a): ${esc(o.seller)}</p><div class="signature"><span>Assinatura do cliente</span><span>Responsável pela entrega</span></div><p class="nonfiscal">PEDIDO DE VENDA · DOCUMENTO NÃO FISCAL<br>Ambiente de demonstração · Gerado em ${new Date().toLocaleString('pt-BR')}</p></article>`}
function storeHeader(){return `${storefront.announcement()}<header class="store-header"><a class="store-logo" href="/loja" aria-label="Grupo Outlet · Página inicial"><img src="assets/logo.webp" alt="Grupo Outlet" width="767" height="272"></a><form class="search" onsubmit="event.preventDefault();catalogQuery=this.q.value;go('/loja/catalogo')">${icon('search')}<input name="q" value="${esc(catalogQuery)}" placeholder="O que sua casa precisa hoje?" aria-label="Buscar produtos"><button aria-label="Buscar">${icon('chevron')}</button></form><div class="actions"><a class="account" href="/loja/conta">${icon('users')}<span>Olá, bem-vindo<small>Minha conta</small></span></a><a class="store-cart" href="/loja/carrinho" aria-label="Carrinho, ${db.cart.reduce((n,i)=>n+i.qty,0)} itens">${icon('cart')}<span class="store-cart-count" aria-hidden="true">${db.cart.reduce((n,i)=>n+i.qty,0)}</span></a></div></header><nav class="store-nav"><a href="/loja/catalogo" onclick="catalogCategory='Todos'">Todos os móveis</a>${db.collections.map((c,i)=>`<a href="/loja/catalogo" onclick="catalogCategory=db.collections[${i}];catalogQuery=''">${esc(c)}</a>`).join('')}</nav>`}
function storeFooter(){return `<footer class="store-footer"><div><img src="assets/logo.webp" alt="Grupo Outlet"><small>Sua casa merece esse cuidado.<br>${esc(db.settings.address)}</small></div><div><strong>Sobre a loja</strong>${db.pages.filter(p=>p.active).map(p=>`<a style="display:block;margin-top:8px" href="/loja/pagina/${p.id}">${esc(p.title)}</a>`).join('')}</div><div><strong>Conte com a gente</strong><a style="display:block;margin-top:8px" href="/loja/conta">Acompanhar meus pedidos</a><a style="display:block;margin-top:8px" href="/app">Acessar o sistema da loja</a><small>Prévia visual · Sem pagamentos reais</small></div></footer>`}
function shopProduct(p){return `<article class="shop-product"><a href="/loja/produto/${p.id}"><div class="product-photo"><span class="badge">Preço de outlet</span><img src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy"></div><h3>${esc(p.name)}</h3></a><div class="price">${money(p.price)}</div><small>${available(p.id)>0?'Disponível · pagamento combinado com a loja':'Temporariamente indisponível'}</small>${button(available(p.id)>0?'Adicionar ao carrinho':'Sem estoque',`onclick="addToCart(${p.id})" ${available(p.id)>0?'':'disabled'}`,'','plus')}</article>`}
function storeHome(){return storefront.storeHome()}
function catalogPage(){const products=db.products.filter(p=>p.active&&(catalogCategory==='Todos'||p.category===catalogCategory)&&p.name.toLowerCase().includes(catalogQuery.toLowerCase()));return `<div class="store-content">${heading(catalogCategory==='Todos'?'Encontre o seu próximo móvel':esc(catalogCategory),'Conforto, praticidade e preços que cabem nos seus planos.')}<div class="toolbar" style="padding:0 0 25px"><form class="search" onsubmit="event.preventDefault();catalogQuery=this.q.value;render()">${icon('search')}<input name="q" value="${esc(catalogQuery)}" placeholder="Buscar na coleção" aria-label="Buscar na coleção"><button aria-label="Buscar">${icon('chevron')}</button></form><div class="actions"><select class="control" style="width:auto" aria-label="Filtrar coleção" onchange="catalogCategory=this.value;render()">${['Todos',...db.collections].map(c=>`<option ${c===catalogCategory?'selected':''}>${esc(c)}</option>`).join('')}</select><span class="subtle">${products.length} produtos</span></div></div><div class="catalog">${products.map(shopProduct).join('')}</div>${products.length?'':'<div class="empty">Nenhum produto encontrado. Experimente outra busca.</div>'}</div>`}
function productPage(id){const p=db.products.find(p=>p.id===id&&p.active);if(!p)return '<div class="empty">Este produto não está disponível. <a href="/loja/catalogo">Voltar ao catálogo</a></div>';return `<div class="store-content"><a class="text-link" href="/loja/catalogo">Loja / ${esc(p.category)}</a><section class="detail-product"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div><span class="badge yellow">Preço de outlet</span><h1>${esc(p.name)}</h1><span class="subtle">Código: ${esc(p.sku)}</span><p>${esc(p.description)}</p><div class="price">${money(p.price)}</div><p style="font-size:13px;margin-top:-10px">Pagamento combinado com nossa equipe pelo WhatsApp.</p><div class="actions"><label class="field" style="max-width:85px">Qtd.<input id="detail-qty" type="number" value="1" min="1" max="${available(p.id)}" aria-label="Quantidade"></label>${button(available(p.id)>0?'Adicionar ao carrinho':'Sem estoque',`onclick="addToCart(${id},Number($('#detail-qty').value))" ${available(p.id)>0?'':'disabled'}`,'primary','bag')}</div><div class="notice" style="margin-top:25px">${available(p.id)>0?'Disponível para pedido. Frete e prazo de entrega serão confirmados no atendimento.':'Avise nossa equipe que você tem interesse neste produto.'}</div><div class="benefit" style="justify-content:flex-start;border:0">${icon('shield')}<div><strong>Você compra com acompanhamento</strong><small>Finalize seu pedido e combine tudo com a nossa equipe.</small></div></div></div></section></div>`}
function addToCart(id,qty=1){const p=db.products.find(p=>p.id===id&&p.active),line=db.cart.find(i=>i.id===id);if(!p||!Number.isInteger(qty)||qty<1||qty+(line?.qty||0)>available(id))return toast('Quantidade indisponível. Confira o estoque.');if(line)line.qty+=qty;else db.cart.push({id,qty});save();render();toast('Produto adicionado ao carrinho.')}
function changeCart(id,delta){const line=db.cart.find(i=>i.id===id);if(!line)return;if(delta>0&&line.qty+delta>available(id))return toast('Você atingiu a quantidade disponível.');line.qty+=delta;if(line.qty<=0)db.cart=db.cart.filter(i=>i.id!==id);save();render()}
const cartTotal=()=>db.cart.reduce((n,i)=>n+(db.products.find(p=>p.id===i.id)?.price||0)*i.qty,0);
function cartPage(){return `<div class="store-content">${heading('Seu carrinho','Falta pouco para deixar sua casa do seu jeito.')} ${db.cart.length?`<div class="two-col"><section class="card pad">${db.cart.map(i=>{const p=db.products.find(p=>p.id===i.id);if(!p)return'';return `<div class="cart-line"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div><h3>${esc(p.name)}</h3><span class="subtle">${money(p.price)} / un.</span><div style="margin-top:10px" class="qty"><button onclick="changeCart(${i.id},-1)" aria-label="Diminuir quantidade">−</button><span>${i.qty}</span><button onclick="changeCart(${i.id},1)" aria-label="Aumentar quantidade">+</button></div></div><div class="right"><strong>${money(p.price*i.qty)}</strong><button style="display:block;margin:15px 0 0 auto" onclick="db.cart=db.cart.filter(i=>i.id!==${i.id});save();render()" aria-label="Remover produto">${icon('trash')}</button></div></div>`}).join('')}<a href="/loja/catalogo" class="text-link" style="display:block;margin-top:23px">Continuar comprando</a></section><section class="card pad" style="align-self:start"><h2>Resumo do pedido</h2><div class="total-line" style="margin-top:20px"><span>Produtos</span><strong>${money(cartTotal())}</strong></div><div class="total-line"><span>Frete</span><span class="subtle">A combinar</span></div><div class="total-line final"><span>Subtotal</span><span>${money(cartTotal())}</span></div><a href="/loja/checkout" class="btn primary" style="width:100%;margin-top:20px">Continuar para os dados</a><p class="subtle" style="line-height:1.7;margin-top:17px">Seu pedido será enviado para análise. O pagamento é combinado com a equipe após a confirmação.</p></section></div>`:`<div class="empty">${icon('bag')}<h2 style="margin:20px 0">Seu carrinho ainda está vazio.</h2><p style="margin-bottom:20px">Encontre o móvel que está faltando na sua casa.</p><a class="btn primary" href="/loja/catalogo">Explorar produtos</a></div>`}</div>`}
function checkoutPage(){if(!db.cart.length)return cartPage();return `<div class="store-content">${heading('Vamos preparar seu pedido','Preencha seus dados. Nossa equipe combina os próximos passos com você.')}<form onsubmit="event.preventDefault();checkout(this)"><div class="two-col"><section class="card pad"><h2 style="margin-bottom:23px">Seus dados</h2><div class="form-grid">${field('Nome completo','customer','','text','required autocomplete="name"')}${field('E-mail','email',sessionStore.getItem('forte-customer')||'','email','required autocomplete="email"')}${field('CPF','cpf','','text','required inputmode="numeric" pattern="[0-9.\u002d]{11,14}" title="Informe o CPF com 11 números"')}${field('Telefone / WhatsApp','phone','','tel','required autocomplete="tel"')}<label class="field full">Como prefere receber?<select name="delivery" onchange="toggleDelivery(this.value)"><option>Entrega</option><option>Retirada</option></select></label></div><div id="delivery-fields" class="form-grid" style="margin-top:23px">${field('CEP','cep','','text','required autocomplete="postal-code"')}${field('Cidade / UF','city','','text','required autocomplete="address-level2"')}${field('Rua / avenida','street','','text','required autocomplete="address-line1"')}${field('Número','number','','text','required')}${field('Bairro','neighborhood','','text','required')}${field('Complemento (opcional)','complement','','text')}</div><h2 style="margin:28px 0 18px">Pagamento</h2><label class="field">Como pretende pagar?<select name="payment"><option>Pix</option><option>Cartão de crédito</option><option>Cartão de débito</option><option>Dinheiro</option></select></label><label class="field" style="margin-top:20px">Observações (opcional)<textarea name="notes" placeholder="Algum detalhe que nossa equipe precisa saber?"></textarea></label></section><section class="card pad" style="align-self:start"><h2>Seu pedido</h2>${db.cart.map(i=>{const p=db.products.find(p=>p.id===i.id);return `<div class="cart-line"><img src="${esc(p.image)}" alt=""><div><h3>${esc(p.name)}</h3><small>${i.qty} × ${money(p.price)}</small></div></div>`}).join('')}<div class="total-line"><span>Frete</span><span class="subtle">A confirmar no atendimento</span></div><div class="total-line final"><span>Subtotal</span><span>${money(cartTotal())}</span></div><div class="notice" style="margin-top:20px">Nenhuma cobrança será feita agora. Seu pedido ficará pendente até a confirmação do pagamento pela equipe.</div><label style="display:flex;gap:9px;font-size:12px;line-height:1.7"><input type="checkbox" required>Estou ciente de que esta é uma demonstração e usarei dados de teste.</label><button class="btn primary" style="width:100%;margin-top:22px">Finalizar pedido</button></section></div></form></div>`}
function toggleDelivery(value){const el=$('#delivery-fields');el.style.display=value==='Retirada'?'none':'grid';el.querySelectorAll('input').forEach(i=>i.required=value!=='Retirada'&&i.name!=='complement')}
function checkout(form){const f=Object.fromEntries(new FormData(form));if(f.cpf.replace(/\D/g,'').length!==11)return toast('Informe um CPF com 11 números.');if(!db.cart.length)return toast('Seu carrinho está vazio.');for(const i of db.cart){const p=db.products.find(p=>p.id===i.id);if(!p?.active||i.qty>available(i.id))return toast('O estoque mudou. Revise o carrinho antes de continuar.')}const o={id:Math.max(...db.orders.map(o=>o.id),1000)+1,date:new Date().toLocaleDateString('en-CA'),customer:f.customer.trim(),email:f.email.trim().toLowerCase(),phone:f.phone,cpf:f.cpf,address:f.delivery==='Retirada'?db.settings.address:`${f.street}, ${f.number}${f.complement?' · '+f.complement:''} · ${f.neighborhood} · ${f.city} · CEP ${f.cep}`,seller:'Ludmilla Santos',channel:'Loja online',items:db.cart.map(i=>{const p=db.products.find(p=>p.id===i.id);return{id:p.id,name:p.name,qty:i.qty,price:p.price,cost:p.cost}}),status:'pending',paid:false,receipt:null,freight:0,freightPending:f.delivery==='Entrega',payment:f.payment,delivery:f.delivery,notes:f.notes};db.orders.unshift(o);db.cart=[];if(!save())return;sessionStore.setItem('forte-customer',o.email);go('/loja/pedido/'+o.id);toast('Pedido criado. A equipe já pode vê-lo no painel.')}
function orderMessage(o){return `Olá, Forte Outlet! Gostaria de confirmar o pedido #${o.id}.\n\nCliente: ${o.customer}\nTelefone: ${o.phone}\nRecebimento: ${o.delivery}\nEndereço: ${o.address}\n\n${o.items.map(i=>`${i.qty} × ${i.name} — ${money(i.price*i.qty)}`).join('\n')}\nSubtotal: ${money(orderTotal(o)-o.freight)}\nFrete: ${o.freightPending?'a combinar':money(o.freight)}\nPagamento: ${o.payment}\n\nAguardo as orientações para pagamento.`}
function customerOrderPage(id){const email=sessionStore.getItem('forte-customer');const o=db.orders.find(o=>o.id===id&&o.email?.toLowerCase()===email?.toLowerCase());if(!o)return accountPage();return `<div class="store-content" style="max-width:850px"><section class="card pad"><div style="text-align:center;padding:15px 0 30px"><span class="task-symbol" style="margin:auto;width:55px;height:55px">${icon('check')}</span><h1 style="margin:18px 0 10px">${o.status==='pending'?'Pedido recebido!':'Acompanhe seu pedido'}</h1><p class="muted" style="font-size:14px">Pedido #${o.id} · ${esc(o.customer)}</p></div><div class="notice">${o.status==='pending'?'Seu pedido está reservado e aguardando pagamento. Continue o atendimento com a equipe para confirmar o frete e a forma de pagamento.':o.status==='ready'?'Pagamento confirmado! Nossa equipe está preparando seu pedido.':o.status==='transit'?'Seu pedido já saiu para entrega.':o.status==='delivered'?'Seu pedido foi concluído. Obrigado por escolher a Forte Outlet.':'Este pedido foi cancelado.'}</div><div class="total-line"><span>Status</span>${badge(o)}</div>${o.items.map(i=>`<div class="total-line"><span>${i.qty} × ${esc(i.name)}</span><strong>${money(i.price*i.qty)}</strong></div>`).join('')}<div class="total-line"><span>Frete</span><span>${o.freightPending?'A combinar':money(o.freight)}</span></div><div class="total-line final"><span>${o.freightPending?'Subtotal':'Total'}</span><span>${money(orderTotal(o))}</span></div><div class="actions" style="margin-top:25px;flex-wrap:wrap">${button('Ver mensagem do pedido',`onclick="messageModal(${id})"`,'primary','phone')}<a class="btn" href="/loja/conta">Meus pedidos</a><a class="btn" href="/loja">Continuar na loja</a></div></section></div>`}
function messageModal(id){const o=db.orders.find(o=>o.id===id);if(!o)return;const phone=db.settings.phone.replace(/\D/g,'');modal('Continuar atendimento',`<p>${phone?'Confira o resumo antes de abrir o WhatsApp. Você decide quando enviar a mensagem.':'O WhatsApp da loja ainda não foi configurado. Você pode copiar a mensagem para testar o fluxo; o proprietário pode adicionar o número em Configurações.'}</p><textarea id="whatsapp-text" readonly style="width:100%;min-height:250px;border:1px solid var(--line);border-radius:7px;padding:14px;font-size:13px;line-height:1.7">${esc(orderMessage(o))}</textarea><div class="form-actions">${button('Copiar mensagem','onclick="copyMessage()"')}${phone?`<a class="btn primary" href="https://wa.me/${phone}?text=${encodeURIComponent(orderMessage(o))}" target="_blank" rel="noopener">Abrir WhatsApp</a>`:''}</div>`)}
async function copyMessage(){try{await navigator.clipboard.writeText($('#whatsapp-text').value);toast('Mensagem copiada.')}catch{$('#whatsapp-text').select();toast('Selecione e copie a mensagem com Ctrl+C.')}}
function accountPage(){const email=sessionStore.getItem('forte-customer');if(!email)return `<div class="store-content" style="max-width:500px;padding-top:55px;padding-bottom:65px"><section class="card pad"><h1>Minha conta</h1><p class="muted" style="font-size:14px;line-height:1.8;margin:15px 0 25px">Acompanhe o preparo e a entrega dos seus pedidos.</p><form onsubmit="event.preventDefault();sessionStore.setItem('forte-customer',this.email.value.toLowerCase().trim());render()">${field('E-mail usado no pedido','email','','email','required placeholder="mariana@exemplo.com"')}<button class="btn primary" style="width:100%;margin-top:20px">Acessar demonstração</button></form><p class="subtle" style="line-height:1.7;margin-top:20px">Login simulado, sem senha. Teste com mariana@exemplo.com ou com o e-mail de um pedido que você criou.</p></section></div>`;const orders=db.orders.filter(o=>o.email?.toLowerCase()===email);return `<div class="store-content" style="max-width:1000px">${heading('Meus pedidos',esc(email),button('Sair','onclick="sessionStore.removeItem(\'forte-customer\');render()"','','logout'))}<div class="notice">Conta de demonstração. A autenticação segura será conectada na próxima etapa.</div><div class="stack">${orders.map(o=>`<section class="card pad"><div class="card-header" style="padding:0 0 20px"><h2>Pedido #${o.id}</h2>${badge(o)}</div><div class="total-line"><span>${o.items.map(i=>esc(i.name)).join(', ')}</span><strong>${money(orderTotal(o))}</strong></div><div class="actions" style="margin-top:18px"><a class="btn" href="/loja/pedido/${o.id}">Acompanhar pedido</a><span class="subtle">${new Date(o.date+'T12:00:00').toLocaleDateString('pt-BR')}</span></div></section>`).join('')||'<div class="empty">Você ainda não tem pedidos com este e-mail. <a href="/loja/catalogo">Explore a loja.</a></div>'}</div></div>`}
function infoPage(id){const p=db.pages.find(p=>p.id===id&&p.active);return `<div class="store-content" style="max-width:850px;min-height:400px">${p?`<h1 style="margin:25px 0">${esc(p.title)}</h1><p style="white-space:pre-wrap;line-height:1.9;color:#646b70">${esc(p.content)}</p>`:'<div class="empty">Página não encontrada.</div>'}</div>`}
function renderStore(){const parts=routePath().split('/'),page=parts[2],id=Number(parts[3]);let content=page==='catalogo'?catalogPage():page==='produto'?productPage(id):page==='carrinho'?cartPage():page==='checkout'?checkoutPage():page==='pedido'?customerOrderPage(id):page==='conta'?accountPage():page==='pagina'?infoPage(id):storeHome();$('#app').innerHTML=`<div class="store">${storeHeader()}${content}${storeFooter()}</div>`;document.title='Forte Outlet · Móveis para sua casa'}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'&&routePath().startsWith('/app')){e.preventDefault();searchModal()}});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_demo_catalog',description:'Read products and available quantities in this local furniture store demonstration.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({products:db.products.filter(p=>p.active).map(p=>({id:p.id,name:p.name,price:p.price,available:available(p.id)}))})})).catch(()=>{})}catch{}}
function editOrderModal(id){const o=visibleOrders().find(o=>o.id===id);if(!o||!canPay()||completed(o)||o.status==='cancelled')return;modal('Editar dados do pedido',`<form onsubmit="event.preventDefault();saveOrderData(this,${id})"><div class="form-grid">${field('Nome do cliente','customer',o.customer,'text','required')}${field('Telefone','phone',o.phone,'tel','required')}${field('Endereço completo','address',o.address,'text','required data-full')}${field('Frete confirmado (R$)','freight',o.freight,'number',`min="0" step="0.01" required ${o.paid?'readonly':''}`)}${field('Previsão de entrega / retirada','deliveryDate',o.deliveryDate||'','date')}<label class="field full">Observações<textarea name="notes">${esc(o.notes)}</textarea></label></div><p class="subtle" style="margin-top:20px">${o.paid?'O frete não pode ser alterado após confirmar o pagamento.':'Salvar confirma o valor do frete combinado com o cliente. Use zero para entrega gratuita ou retirada.'}</p><div class="form-actions"><button class="btn primary">Salvar dados do pedido</button></div></form>`)}
function saveOrderData(form,id){const o=visibleOrders().find(o=>o.id===id);if(!o||!canPay()||completed(o)||o.status==='cancelled')return;const f=Object.fromEntries(new FormData(form));Object.assign(o,{customer:f.customer,phone:f.phone,address:f.address,notes:f.notes,deliveryDate:f.deliveryDate,freight:o.paid?o.freight:Number(f.freight),freightPending:false});save();closeModal();render();toast('Dados do pedido atualizados.')}
